using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Appearance;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NewGameWorldTests
{
    internal static RegisteredOfficer Officer(string id="created:test",StartTemplate role=StartTemplate.Ronin,string site="site:castle",string? lord=null)=>new(id,null,"鏡山 宗久",1520,new(60,50,70,40),role,site,lord,role==StartTemplate.Daimyo?"鏡山家":null,AppearanceCatalog.Default(1));
    internal static (SetupScenario World,RegisteredOfficer[] Registered) Setup(RegisteredOfficer[]? records=null,DaimyoPlacement[]? placements=null){var normalized=NewGameWorld.Normalize(records??[Officer()]);var p=NewGameSetup.Preview(NewGameWorld.Scenario(),new(normalized,placements??[]));Assert.True(p.IsEligible(),string.Join(',',p.Errors));return(NewGameSetup.Confirm(NewGameWorld.Scenario(),new(normalized,placements??[]),p),normalized);}
    internal static WorldSession Session(RegisteredOfficer[]? records=null,string selected="created:test"){var setup=Setup(records);return new(NewGameWorld.Create(setup.World,setup.Registered,selected));}
    internal static void At(WorldSession s,long at){while(s.Seconds<at){s.SetPaused(false);long before=s.Seconds;s.AdvanceTo(at);Assert.True(s.Seconds>before);}}
    [Fact]public void CreatedStartPreservesIdentityLookAndOwnKnowledgeOnly(){var s=Session();var w=s.DiagnosticSnapshot();Assert.Equal(new EntityId("created:test"),s.PlayerControl);Assert.Equal(4,w.Characters.Length);Assert.Equal(ContractJson.CanonicalHash(AppearanceCatalog.Default(1)),ContractJson.CanonicalHash(NewGameWorld.Look(w.NewGame!,"created:test")));Assert.Empty(w.Units);Assert.Empty(w.ServiceBonds);Assert.All(s.GetActorView(s.PlayerControl).Evidence,e=>Assert.Equal(s.PlayerControl,e.Subject));Assert.DoesNotContain(w.Grants,g=>g.Actions.Contains(ActionKind.Transfer));}
    [Theory][InlineData("person:nobunaga")][InlineData("person:shingen")][InlineData("person:ujiyasu")]
    public void HistoricalPersonIsSelectableAndCanTravel(string id){var setup=Setup([]);var s=new WorldSession(NewGameWorld.Create(setup.World,[],id));var w=s.DiagnosticSnapshot();string start=NewGameWorld.InitialNode(w,s.PlayerControl);Assert.Equal(NationalRoutes.Nodes.Single(n=>n.Id==start).Position,s.GetBranchView(s.PlayerControl).Position);string goal=start=="castle"?"fork":"castle";Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(w,"request:go",goal),s.Revision).Code);At(s,3);Assert.Contains(s.DiagnosticSnapshot().Branches!.Journeys,j=>j.Actor==s.PlayerControl);}
    [Theory][InlineData("site:kofu")][InlineData("site:odawara")][InlineData("castle:kiyosu")]
    public void RegisteredSiteAliasesAndNonKiyosuStartAreContinuous(string site){var s=Session([Officer(site:site)]);Assert.Equal(NationalRoutes.Nodes.Single(n=>n.Id==NewGameWorld.Node(site)).Position,s.GetBranchView(s.PlayerControl).Position);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:trip",site=="castle:kiyosu"?"fork":"castle"),s.Revision).Code);At(s,10);ContractValidation.Validate(s.DiagnosticSnapshot());}
    [Fact]public void RoninCanHavePersonalRetinue(){var list=new[]{Officer(),Officer("created:follower",StartTemplate.Retainer,lord:"created:test")};var s=Session(list);var w=s.DiagnosticSnapshot();Assert.Contains(w.ServiceBonds,b=>b.Subject.Value=="created:follower"&&b.Target==s.PlayerControl);Assert.DoesNotContain(w.Memberships,m=>m.Subject==s.PlayerControl||m.Subject.Value=="created:follower");}
    [Fact]public void GroupSourceLordResolvesToIndependentCopy(){var boss=Officer() with{Id="created:copy-boss",CopiedFrom="created:test"};var follower=Officer("created:follower",StartTemplate.Retainer,lord:"created:test");var setup=Setup([follower,boss]);Assert.Equal("created:copy-boss",setup.World.People.Single(p=>p.Id==follower.Id).Lord);}
    [Fact]public void UnresolvedLordAndCycleRejectBeforeWorldCreation(){var bad=Officer("created:one",StartTemplate.Retainer,lord:"created:missing");Assert.False(NewGameSetup.Preview(NewGameWorld.Scenario(),new([bad],[])).IsEligible());var a=bad with{Lord="created:two"};var b=bad with{Id="created:two",Lord=a.Id};Assert.False(NewGameSetup.Preview(NewGameWorld.Scenario(),new([a,b],[])).IsEligible());}
    [Fact]public void NewDaimyoAllocationAndOldLordRoninSurviveConversion(){var p=Officer(role:StartTemplate.Daimyo);var setup=Setup([p],[new(p.Id,"org:created-test",[p.Site],false)]);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,p.Id));var w=s.DiagnosticSnapshot();Assert.Contains(w.LandRights,l=>l.Subject.Value=="org:created-test"&&l.Target.Value==p.Site);Assert.DoesNotContain(w.Memberships,m=>m.Subject.Value=="person:nobunaga");Assert.Contains(w.Offices,o=>o.Subject.Value==p.Id&&o.Kind=="house-head");Assert.Empty(w.Units);}
    [Fact]public void InspectAndTravelUseExistingEffectsAndMessages(){var s=Session();Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),"request:inspect"),s.Revision).Code);At(s,8);Assert.Contains(s.DiagnosticSnapshot().EffectLedger,e=>e.Result=="completed");Assert.NotEmpty(s.GetActorView(s.PlayerControl).Messages);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:move","fork"),s.Revision).Code);At(s,30);ContractValidation.Validate(s.DiagnosticSnapshot());}
    [Fact]public void SaveRestoresAndContinuesExactWorld(){var s=Session();s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:move","fork"),s.Revision);At(s,5);s.SetPaused(true);var original=s.DiagnosticSnapshot();var dir=Path.Combine(Path.GetTempPath(),"hakutai-new-game-tests",Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(dir,original.Definitions);store.Save(s,"manual",original.WorldId);var host=new WorldSessionHost(new WorldSession(original));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.CanonicalHash(original),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));At(s,80);At(host.Current,80);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}
    [Theory][InlineData("look")][InlineData("birth")][InlineData("lord")][InlineData("land")][InlineData("scope")][InlineData("metadata")][InlineData("position")]
    public void ForgedWorldCannotLoad(string change){var s=Session();var w=s.DiagnosticSnapshot();if(change=="look")w.NewGame!.Registered[0].Look!.SkinLinear[0]=.1f;if(change=="birth")w.NewGame!.Registered[0]=w.NewGame.Registered[0] with{BirthYear=1559};if(change=="lord")w.ServiceBonds=[new(new("service:forged"),s.PlayerControl,new("person:nobunaga"),"service",NewGameWorld.Basis,0,long.MaxValue,0)];if(change=="land")w.LandRights=[];if(change=="scope")w.Grants=[..w.Grants,new(new("grant:evil"),s.PlayerControl,s.PlayerControl,ContractFixture.Castle,[ActionKind.Transfer],NewGameWorld.Basis,0,long.MaxValue,1,[],false,0)];if(change=="metadata")w.NewGame=null;if(change=="position")w.Locations=w.Locations.Select(l=>l.Actor==s.PlayerControl?l with{Site=new("site:kofu")}:l).ToArray();Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact]public void MinorMayAppearButCannotBePlayer(){var p=Officer() with{BirthYear=1550};var setup=Setup([p]);Assert.Throws<InvalidDataException>(()=>NewGameWorld.Create(setup.World,setup.Registered,p.Id));var world=NewGameWorld.Create(setup.World,setup.Registered,"person:nobunaga");Assert.Equal(LifeState.Minor,world.Characters.Single(c=>c.Id.Value==p.Id).Life);}
    [Fact]public void SameSeedAndSetupProduceIdenticalStart(){var setup=Setup();Assert.Equal(ContractJson.Write(NewGameWorld.Create(setup.World,setup.Registered,"created:test",42)),ContractJson.Write(NewGameWorld.Create(setup.World,setup.Registered,"created:test",42)));}
    [Fact]public void BudgetAndMalformedLookRejectBeforeBegin(){var p=Officer() with{Attributes=new(101,1,1,1)};var setup=Setup([p]);Assert.Throws<InvalidDataException>(()=>NewGameWorld.Create(setup.World,setup.Registered,p.Id));p=Officer();p.Look!.SkinLinear=[float.NaN,0,0];Assert.ThrowsAny<Exception>(()=>NewGameWorld.Normalize([p]));}
    [Fact]public void LegacyLiteralWorldsStillRoundTripWithoutNewModule(){foreach(var name in new[]{"initial","active"}){var bytes=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","military-bd631ba-"+name+".json"));var w=ContractJson.Read<ContractWorld>(bytes);ContractValidation.Validate(w);Assert.Null(w.NewGame);Assert.Equal(bytes,ContractJson.Write(w));}}
}
